import json, sys
sys.path.insert(0, "/tmp")
from probe import probe, extract, dec

results = {}
# Task 2: light vs dark backgrounds
bgs = ["rgb:0000/0000/0000", "rgb:ffff/ffff/ffff", "rgb:8080/8080/8080",
       "rgb:7777/7777/7777", "rgb:9999/9999/9999",
       "rgb:2f2f/2f2f/2f2f", "rgb:3030/3030/3030",
