                     ("truecolor", {"TERM":"xterm-256color","COLORTERM":"truecolor"})]:
    for bg in bgs:
        try:
            out, alive = probe(env=env, bg=bg)
            key = f"{envname}|bg={bg}"
            results[key] = {"alive": alive, **dec(extract(out))}
            print(f"{key}: {results[key]}", flush=True)
        except Exception as ex:
            print(f"{envname}|bg={bg}: ERROR {ex}", flush=True)

json.dump(results, open("/tmp/A2_bg_matrix.json","w"), indent=1)
print("DONE")

