import json, re, math
t=json.load(open('/tmp/A2_color_table.json'))
def code(c):
    m=re.search(r'48;5;(\d+)', c['selected'])
    return int(m.group(1)) if m else None
pal={}
for i in range(216):
    pal[16+i]=(0 if i//36==0 else 55+40*(i//36), 0 if (i%36)//6==0 else 55+40*((i%36)//6), 0 if i%6==0 else 55+40*(i%6))
for i in range(24):
    pal[232+i]=(8+10*i,)*3
def srgb2lin(c):
    c/=255.0
    return c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4
def lab(r,g,b):
    R,G,B=srgb2lin(r),srgb2lin(g),srgb2lin(b)
    X=(0.4124*R+0.3576*G+0.1805*B)/0.95047
    Y=(0.2126*R+0.7152*G+0.0722*B)/1.0
    Z=(0.0193*R+0.1192*G+0.9505*B)/1.08883
    def f(t): return t**(1/3) if t>0.008856 else 7.787*t+16/116
    fx,fy,fz=f(X),f(Y),f(Z)
    return (116*fy-16, 500*(fx-fy), 200*(fy-fz))
palab={i:lab(*c) for i,c in pal.items()}
def nearest_cie76(r,g,b):
    l1=lab(r,g,b)
    best=None;bd=1e18
    for i in range(16,256):
        l2=palab[i]
        d=sum((a-b)**2 for a,b in zip(l1,l2))
        if d<bd: bd=d;best=i
    return best
mism=0;tot=0
for hexs,v in t.items():
    r,g,b=int(hexs[1:3],16),int(hexs[3:5],16),int(hexs[5:7],16)
    got=code(v)
    if got is None: continue
    tot+=1
    if nearest_cie76(r,g,b)!=got:
        mism+=1
        if mism<10: print('MISM',hexs,'got',got,'cie76',nearest_cie76(r,g,b))
print('cie76 mismatches:',mism,'/',tot)
"

